use thiserror::Error;

/// Defines the API for the server generated by tonic.
// clippy 1.99 (CI installs the latest stable) flags the generated code:
// async-trait's `#[must_use]` methods and `tonic::Status` as a large error.
#[allow(
    clippy::nursery,
    clippy::pedantic,
    clippy::double_must_use,
    clippy::result_large_err
)]
pub mod api {
    tonic::include_proto!("ibc_attestor");

    pub(crate) const FILE_DESCRIPTOR_SET: &[u8] =
        tonic::include_file_descriptor_set!("ibc_attestor_descriptor");
}

mod attestor;
/// HTTP health server for readiness probes
pub mod health;
mod interceptor;
mod middleware;
/// Server implementation and assembly
pub mod server;

pub use interceptor::tracing_interceptor;
pub use middleware::LoggingMiddleware;

/// Errors that can occur during RPC operations.
#[derive(Debug, Error)]
pub enum RpcError {
    /// Error from the Tonic transport layer.
    #[error("TonicError: {0}")]
    TonicError(#[from] tonic::transport::Error),
}
